BEGIN;
CREATE TEMP TABLE t (id bigserial primary key, account_id bigint not null, status text not null, updated_at timestamp(6) not null);
INSERT INTO t (account_id, status, updated_at)
  SELECT (g % 4) + 1, (ARRAY['open','pending','solved'])[(g % 3) + 1], now() - (g || ' seconds')::interval FROM generate_series(1, 200000) g;
CREATE INDEX ON t (account_id, updated_at DESC, id DESC);
CREATE INDEX ON t (account_id, status, updated_at DESC, id DESC);
ANALYZE t;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) SELECT * FROM t WHERE account_id = 1 AND (updated_at, id) < (now() - interval '150000 seconds', 150000) ORDER BY updated_at DESC, id DESC LIMIT 26;
