EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) SELECT * FROM t WHERE account_id = 1 ORDER BY updated_at DESC, id DESC LIMIT 26 OFFSET 45000;
ROLLBACK;
SQL

